create extension if not exists pgcrypto;
create type public.user_role as enum ('admin','manager','teacher','viewer');
create type public.class_status as enum ('active','upcoming','finished');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role public.user_role default 'viewer', phone text, created_at timestamptz default now());
create table if not exists public.teachers(id uuid primary key default gen_random_uuid(), full_name text not null, phone text, email text, status text default 'active', created_at timestamptz default now());
create table if not exists public.rooms(id uuid primary key default gen_random_uuid(), name text not null unique, capacity int default 20);
create table if not exists public.classes(id uuid primary key default gen_random_uuid(), name text not null, level text, teacher_id uuid references public.teachers(id), room_id uuid references public.rooms(id), start_date date, end_date date, schedule_text text, tuition numeric(12,2) default 0, capacity int default 20, status public.class_status default 'active', created_at timestamptz default now());
create table if not exists public.students(id uuid primary key default gen_random_uuid(), student_code text unique, full_name text not null, dob date, phone text, parent_phone text, email text, class_id uuid references public.classes(id), enroll_date date default current_date, status text default 'active', notes text, created_at timestamptz default now());
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(), class_id uuid references public.classes(id) on delete cascade, student_id uuid references public.students(id) on delete cascade, lesson_date date not null, status text check(status in ('present','absent','late','excused')), note text, unique(student_id,lesson_date));
create table if not exists public.fees(id uuid primary key default gen_random_uuid(), student_id uuid references public.students(id) on delete cascade, month date not null, amount_due numeric(12,2) default 0, amount_paid numeric(12,2) default 0, paid_at timestamptz, note text, unique(student_id,month));
create index if not exists idx_students_class on public.students(class_id); create index if not exists idx_attendance_date on public.attendance(lesson_date); create index if not exists idx_fees_month on public.fees(month);
alter table public.profiles enable row level security; alter table public.teachers enable row level security; alter table public.rooms enable row level security; alter table public.classes enable row level security; alter table public.students enable row level security; alter table public.attendance enable row level security; alter table public.fees enable row level security;
create or replace function public.current_role() returns public.user_role language sql stable security definer set search_path=public as $$ select coalesce((select role from public.profiles where id=auth.uid()),'viewer'::public.user_role) $$;
create policy "authenticated read profiles" on public.profiles for select to authenticated using (true);
create policy "staff read" on public.classes for select to authenticated using (true); create policy "staff read students" on public.students for select to authenticated using (true); create policy "staff read teachers" on public.teachers for select to authenticated using (true); create policy "staff read rooms" on public.rooms for select to authenticated using (true); create policy "staff read attendance" on public.attendance for select to authenticated using (true); create policy "staff read fees" on public.fees for select to authenticated using (true);
create policy "manager write classes" on public.classes for all to authenticated using (public.current_role() in ('admin','manager')) with check (public.current_role() in ('admin','manager'));
create policy "manager write students" on public.students for all to authenticated using (public.current_role() in ('admin','manager')) with check (public.current_role() in ('admin','manager'));
create policy "manager write teachers" on public.teachers for all to authenticated using (public.current_role() in ('admin','manager')) with check (public.current_role() in ('admin','manager'));
create policy "manager write rooms" on public.rooms for all to authenticated using (public.current_role() in ('admin','manager')) with check (public.current_role() in ('admin','manager'));
create policy "staff attendance" on public.attendance for all to authenticated using (public.current_role() in ('admin','manager','teacher')) with check (public.current_role() in ('admin','manager','teacher'));
create policy "manager fees" on public.fees for all to authenticated using (public.current_role() in ('admin','manager')) with check (public.current_role() in ('admin','manager'));
